module find_number_small(\n    input clk,\n    input rst_n,\n    input start,\n    input [5:0] m,\n    input [5:0] n,\n    input [7:0] p,\n    input [7:0] q,\n    output reg [31:0] result,\n    output reg done,\n    output reg valid\n);\n\n    localparam [3:0] IDLE       = 4'd0;\n    localparam [3:0] INIT       = 4'd1;\n    localparam [3:0] ITER       = 4'd2;\n    localparam [3:0] FINISH     = 4'd3;\n\n    reg [3:0] state;\n\n    reg [5:0] m_reg;\n    reg [5:0] n_reg;\n    reg [7:0] p_reg;\n    reg [7:0] q_reg;\n    reg [31:0] current_A;\n    reg [31:0] best_N;\n    reg found_flag;\n    reg [31:0] L_value;\n    reg [31:0] M_power;\n    reg [31:0] min_N_val;\n    reg [31:0] max_N_val;\n    reg [2:0] d_value;\n\n    wire [31:0] power_10_d = (d_value == 3'd3) ? 32'd1000 :\n                             (d_value == 3'd2) ? 32'd100  :\n                             (d_value == 3'd1) ? 32'd10   : 32'd1;\n    \n    wire [31:0] current_B = current_A * power_10_d + p_reg;\n    wire [31:0] current_N = q_reg * current_B;\n    wire current_valid    = (current_N >= min_N_val) && (current_N <= max_N_val) &&\n                          ((L_value == 32'd0) ? 1'b1 : (current_N % M_power) == current_A);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            result <= 32'd0;\n            current_A <= 32'd0;\n            best_N <= 32'd0;\n            found_flag <= 1'b0;\n            L_value <= 32'd0;\n            M_power <= 32'd0;\n            min_N_val <= 32'd0;\n            max_N_val <= 32'd0;\n            d_value <= 3'd0;\n            m_reg <= 6'd0;\n            n_reg <= 6'd0;\n            p_reg <= 8'd0;\n            q_reg <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done    <= 1'b0;\n                    valid   <= 1'b0;\n                    current_A <= 32'd0;\n                    if (start) begin\n                        m_reg   <= m;\n                        n_reg   <= n;\n                        p_reg   <= p;\n                        q_reg   <= q;\n                        state   <= INIT;\n                    end\n                end\n                \n                INIT: begin\n                    L_value <= {26'd0, m_reg} - {26'd0, n_reg};\n                    case (m_reg)\n                        6'd1: min_N_val <= 32'd1;\n                        6'd2: min_N_val <= 32'd10;\n                        6'd3: min_N_val <= 32'd100;\n                        6'd4: min_N_val <= 32'd1000;\n                        6'd5: min_N_val <= 32'd10000;\n                        6'd6: min_N_val <= 32'd100000;\n                        default: min_N_val <= 32'd0;\n                    endcase\n                    case (m_reg)\n                        6'd1: max_N_val <= 32'd9;\n                        6'd2: max_N_val <= 32'd99;\n                        6'd3: max_N_val <= 32'd999;\n                        6'd4: max_N_val <= 32'd9999;\n                        6'd5: max_N_val <= 32'd99999;\n                        6'd6: max_N_val <= 32'd999999;\n                        default: max_N_val <= 32'd0;\n                    endcase\n                    case (L_value[3:0])\n                        4'd0: M_power <= 32'd1;\n                        4'd1: M_power <= 32'd10;\n                        4'd2: M_power <= 32'd100;\n                        4'd3: M_power <= 32'd1000;\n                        4'd4: M_power <= 32'd10000;\n                        4'd5: M_power <= 32'd100000;\n                        4'd6: M_power <= 32'd1000000;\n                        default: M_power <= 32'd1;\n                    endcase\n                    found_flag <= 1'b0;\n                    best_N <= 32'd0;\n                    state <= ITER;\n                end\n                \n                ITER: begin\n                    if (current_A < M_power) begin\n                        if (current_valid) begin\n                            if (!found_flag || (current_N < best_N)) begin\n                                best_N <= current_N;\n                                found_flag <= 1'b1;\n                            end\n                        end\n                        current_A <= current_A + 32'd1;\n                    end else begin\n                        result <= found_flag ? best_N : 32'd0;\n                        state <= FINISH;\n                    end\n                end\n\n                FINISH: begin\n                    done  <= 1'b1;\n                    valid <= found_flag;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule